# Auto-generated embedded StockLens dashboard for Vercel serverless deployment.
# Keep this file inside api/ so Vercel always includes it with api/index.py.

DASHBOARD_HTML = '<!doctype html>\n<html>\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>StockLens AI</title>\n<style>\n\n*{box-sizing:border-box}\nbody{margin:0;background:#061224;color:#eaf2ff;font:15px Arial,sans-serif}\nheader{height:72px;border-bottom:1px solid #18304b;display:flex;justify-content:space-between;align-items:center;padding:0 max(6vw,24px)}\nheader b{font-size:22px}\nheader span,label{color:#55dfc4}\nheader small{display:block;color:#7e91aa;margin-top:3px}\nheader i{font-style:normal;color:#9fb1c8;font-size:12px}\nmain{max-width:1050px;margin:auto;padding:34px 20px}\n.hero,.controls,article,.price-panel{background:#0b1a2e;border:1px solid #18304b;border-radius:20px}\n.hero{padding:35px}\n.hero h1{font-size:43px;margin:12px 0}\n.hero p{color:#91a3bb;max-width:760px;line-height:1.6}\n\n.tabs{display:flex;gap:10px;margin-bottom:18px}\nbutton{height:44px;border:0;border-radius:9px;background:#55dfc4;color:#05251f;font-weight:bold;cursor:pointer}\n.tabs .tab{background:#0b1a2e;color:#9fb1c8;border:1px solid #18304b;padding:0 18px}\n.tabs .active{background:#55dfc4;color:#05251f}\n\n.price-panel{margin:18px 0;padding:20px}\n.price-head{display:flex;justify-content:space-between;gap:20px;align-items:end}\n.price-head small{color:#55dfc4;font-size:11px;font-weight:bold}\n.price-head h3{font-size:24px;margin:6px 0 0}\n.price-note{color:#7890aa;font-size:12px;max-width:360px;text-align:right}\n\n.dual-slider{position:relative;height:44px;margin:18px 0 0}\n.dual-slider:before{content:"";position:absolute;left:0;right:0;top:21px;height:5px;border-radius:10px;background:#203854}\n.dual-slider input[type=range]{position:absolute;left:0;top:7px;width:100%;height:30px;background:transparent;pointer-events:none;-webkit-appearance:none;appearance:none}\n.dual-slider input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:22px;height:22px;border-radius:50%;background:#55dfc4;border:3px solid #071426;pointer-events:auto;cursor:pointer}\n.dual-slider input[type=range]::-moz-range-thumb{width:18px;height:18px;border-radius:50%;background:#55dfc4;border:3px solid #071426;pointer-events:auto;cursor:pointer}\n.range-labels{display:flex;justify-content:space-between;color:#71869f;font-size:12px}\n.chips{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}\n.chips button{height:34px;background:#10253d;color:#b7c7d9;border:1px solid #203854;padding:0 12px}\n.chips button:hover{border-color:#55dfc4;color:#55dfc4}\n\n.controls{margin:18px 0;padding:18px;display:grid;grid-template-columns:1.4fr 1fr 1fr 1.2fr;gap:12px;align-items:end}\n.controls small,.forecast small,.afford small{display:block;color:#8094ad;margin-bottom:7px}\n.money,select{height:44px;background:#071426;border:1px solid #203854;border-radius:9px;color:white;padding:0 12px}\n.money{display:flex;align-items:center}\n.money input{width:100%;background:transparent;border:0;color:white;font-size:16px;outline:0}\nselect{width:100%}\n.status{padding:15px;color:#9eb0c7}\n.title{display:flex;justify-content:space-between;align-items:end}\n.title h2{margin:7px 0 15px;font-size:26px}\n.title>small{color:#8094ad}\n\narticle{padding:20px;margin-bottom:16px}\n.top{display:flex;justify-content:space-between;border-bottom:1px solid #18304b;padding-bottom:14px}\n.top h3{display:inline;margin:0 10px;font-size:23px}\n.top em{background:#102b49;color:#74baff;padding:7px;border-radius:8px}\n.top small{color:#8195ae}\n.score{font-size:32px;text-align:right}\n.score small{font-size:11px;color:#8195ae;display:block;margin-top:4px}\n\n.afford,.forecast{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;padding-top:17px}\n.afford div{background:#0d2638;border:1px solid #1c4555;border-radius:12px;padding:14px}\n.afford b{font-size:17px;color:#55dfc4}\n.forecast div{background:#071426;border:1px solid #18304b;border-radius:12px;padding:14px}\n.forecast b{font-size:16px}\n\n.meta{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}\n.meta span{background:#10253d;padding:7px 10px;border-radius:15px;color:#a9bbcf;font-size:12px}\n.why{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:14px}\n.why>div{background:#071426;padding:15px;border-radius:12px;color:#a7b7ca}\n.why b{color:#55dfc4}\n.why li{margin:7px 0}\n.empty{background:#0b1a2e;border:1px dashed #31516e;border-radius:18px;padding:32px;text-align:center;color:#8fa4bc;line-height:1.7}\n.empty b{color:#eaf2ff;font-size:19px}\n.foot{text-align:center;color:#71869f;margin:30px}\n.hide{display:none!important}\n\n@media(max-width:750px){\n  .hero h1{font-size:34px}\n  .controls,.forecast,.afford,.why{grid-template-columns:1fr}\n  .controls button{margin-top:5px}\n  .price-head{display:block}\n  .price-note{text-align:left;margin-top:10px}\n  .tabs{display:grid;grid-template-columns:1fr 1fr}\n  .tabs .tab{padding:0 8px}\n}\n\n\n/* v0.7 Accuracy & Backtest */\n.tabs{grid-template-columns:repeat(3,minmax(0,1fr))}\n.backtest-controls{grid-template-columns:1.4fr 1fr 1fr 1fr}\n.accuracy-card{padding:22px}\n.scope{display:flex;justify-content:space-between;gap:18px;align-items:center;padding:14px 16px;border-radius:12px;margin-bottom:16px}\n.scope b{font-size:12px;letter-spacing:.04em}\n.scope span{font-size:12px;color:#a7b7ca;text-align:right}\n.good-scope{background:#0b302c;border:1px solid #1d5b50}\n.good-scope b{color:#55dfc4}\n.proxy-scope{background:#302713;border:1px solid #66501f}\n.proxy-scope b{color:#f1c45b}\n.metrics-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:16px 0}\n.metric{background:#071426;border:1px solid #18304b;border-radius:14px;padding:16px;min-height:98px}\n.metric small{display:block;color:#8094ad;margin-bottom:10px}\n.metric strong{display:block;font-size:28px;color:#eaf2ff}\n.metric span{display:block;color:#71869f;font-size:11px;margin-top:6px}\n.outcome-strip{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0 22px}\n.outcome-strip span{background:#10253d;color:#9fb2c8;padding:8px 10px;border-radius:16px;font-size:12px}\n.breakdown-block{margin-top:22px}\n.breakdown-block h3{font-size:17px;margin:0 0 10px}\n.table-wrap{overflow-x:auto;border:1px solid #18304b;border-radius:12px}\ntable{width:100%;border-collapse:collapse;min-width:580px;background:#071426}\nth,td{padding:11px 12px;text-align:left;border-bottom:1px solid #142b43;font-size:12px}\nth{color:#7f96ae;font-weight:600;background:#0a192b}\ntd{color:#b7c5d6}\ntr:last-child td{border-bottom:0}\n.caveat{margin-top:22px;background:#0a1727;border:1px solid #203854;border-radius:12px;padding:15px;color:#91a5ba}\n.caveat b{color:#d9e5f3}\n.caveat li{margin:7px 0;line-height:1.45}\n.caveat.important{border-color:#66501f;background:#211d12}\n\n@media(max-width:750px){\n  .tabs{grid-template-columns:1fr}\n  .backtest-controls,.metrics-grid{grid-template-columns:1fr}\n  .scope{display:block}\n  .scope span{display:block;text-align:left;margin-top:6px}\n}\n\n/* v0.8 Strategy Lab */\n.compare-head,.compare-row{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:10px;align-items:center;padding:12px 14px}\n.compare-head{background:#0a192b;border:1px solid #18304b;border-radius:12px 12px 0 0;color:#8094ad;font-size:12px}\n.compare-row{border:1px solid #18304b;border-top:0;background:#071426}\n.compare-row span{color:#a5b5c7}.compare-row b{font-size:17px}\n.compare-row .better{color:#55dfc4}.compare-row .worse{color:#f0a0a0}\n@media(max-width:750px){.compare-head,.compare-row{grid-template-columns:1.3fr .8fr 1fr;font-size:12px}}\n\n.optimizer-btn{background:#1a3657!important}.verdict{padding:5px 9px;border-radius:12px}.verdict.pass{background:#123d31;color:#61e2bd}.verdict.fail{background:#44202a;color:#ff9dad}.wf-head,.wf-row{display:grid;grid-template-columns:1.4fr repeat(3,1fr);gap:8px;padding:11px 13px;border:1px solid #18304b}.wf-head{background:#0a192b;color:#8196ad}.wf-row{border-top:0;background:#071426}.baseline-box{display:grid;grid-template-columns:1.5fr repeat(4,1fr);gap:8px;margin-top:18px;padding:14px;background:#0a192b;border:1px solid #18304b;border-radius:12px}@media(max-width:750px){.wf-head,.wf-row{font-size:11px}.baseline-box{grid-template-columns:1fr 1fr}}\n\n</style>\n</head>\n<body>\n<header>\n  <div>\n    <b>StockLens <span>AI</span></b>\n    <small>Analyze. Rank. Trade Smarter.</small>\n  </div>\n  <i>● Data-driven research</i>\n</header>\n\n<main>\n  <div class="tabs">\n    <button class="tab active" onclick="mode(\'invest\',this)">📈 1-Month Investing</button>\n    <button class="tab" onclick="mode(\'day\',this)">⚡ Intraday Trading</button>\n    <button class="tab" onclick="mode(\'backtest\',this)">📊 Accuracy & Backtest</button>\n    <button class="tab" onclick="mode(\'lab\',this)">🧪 Strategy Lab</button>\n  </div>\n\n  <section class="hero">\n    <label id="eyebrow">1-MONTH INVESTMENT FINDER</label>\n    <h1 id="headline">Find strong 1-month stock candidates.</h1>\n    <p id="copy">\n      Enter your investment amount and StockLens will rank the strongest 1-month candidates.\n    </p>\n  </section>\n\n  <section id="pricePanel" class="price-panel hide">\n    <div class="price-head">\n      <div>\n        <small>INTRADAY STOCK PRICE FILTER</small>\n        <h3 id="priceText">Any affordable price</h3>\n      </div>\n      <div class="price-note">This filter applies only to Intraday Trading.</div>\n    </div>\n\n    <div class="dual-slider">\n      <input id="minPrice" type="range" min="0" max="5000" step="50" value="0" oninput="priceChanged(\'min\')">\n      <input id="maxPrice" type="range" min="0" max="5000" step="50" value="5000" oninput="priceChanged(\'max\')">\n    </div>\n\n    <div class="range-labels">\n      <span>₹0</span>\n      <span>₹5,000+</span>\n    </div>\n\n    <div class="chips">\n      <button onclick="preset(0,5000)">Any Affordable</button>\n      <button onclick="preset(0,200)">Under ₹200</button>\n      <button onclick="preset(0,500)">Under ₹500</button>\n      <button onclick="preset(500,1000)">₹500–₹1,000</button>\n      <button onclick="preset(1000,2500)">₹1,000–₹2,500</button>\n    </div>\n  </section>\n\n  <section id="mainControls" class="controls">\n    <div>\n      <small>Capital / investment amount</small>\n      <div class="money">₹ <input id="amount" type="number" value="5000" min="1000"></div>\n    </div>\n\n    <div id="riskbox">\n      <small>Risk profile</small>\n      <select id="risk">\n        <option>low</option>\n        <option selected>moderate</option>\n        <option>high</option>\n      </select>\n    </div>\n\n    <div id="riskpct" class="hide">\n      <small>Risk per trade</small>\n      <select id="rp">\n        <option value=".5">0.5%</option>\n        <option value="1" selected>1%</option>\n        <option value="1.5">1.5%</option>\n        <option value="2">2%</option>\n      </select>\n    </div>\n\n    <div>\n      <small>Stocks to analyze</small>\n      <select id="limit">\n        <option>5</option>\n        <option selected>10</option>\n        <option>20</option>\n      </select>\n    </div>\n\n    <button id="go" onclick="run()">Find Best Stocks</button>\n  </section>\n\n  <section id="backtestControls" class="controls backtest-controls hide">\n    <div>\n      <small>Engine to test</small>\n      <select id="btEngine" onchange="backtestEngineChanged()">\n        <option value="intraday" selected>Intraday — same live rules</option>\n        <option value="monthly">1-Month — technical proxy</option>\n      </select>\n    </div>\n\n    <div>\n      <small>Representative stocks</small>\n      <select id="btLimit">\n        <option value="3" selected>3 — Fast</option>\n        <option value="5">5 — Better sample</option>\n      </select>\n    </div>\n\n    <div id="btWindowBox">\n      <small>Historical window</small>\n      <select id="btWindow">\n        <option value="5d">5 trading days</option>\n        <option value="1mo" selected>About 1 month</option>\n      </select>\n    </div>\n\n    <div id="btMonthlyBox" class="hide">\n      <small>1-month history</small>\n      <select id="btMonthlyPeriod">\n        <option value="1y">1 year</option>\n        <option value="2y" selected>2 years</option>\n      </select>\n    </div>\n\n    <button onclick="runBacktest()">Run Backtest</button>\n  </section>\n\n  <section id="labControls" class="controls hide">\n    <div>\n      <small>Strategy to improve</small>\n      <select id="labEngine">\n        <option value="intraday" selected>Intraday</option>\n        <option value="monthly">1-Month technical proxy</option>\n      </select>\n    </div>\n    <div>\n      <small>Representative stocks</small>\n      <select id="labLimit"><option value="3">3 — Fast</option><option value="5" selected>5 — Better sample</option></select>\n    </div>\n    <div><small>Comparison</small><div class="money">v0.7 baseline → v0.8 candidate</div></div>\n    <button onclick="runLab()">Compare Strategies</button><button class="optimizer-btn" onclick="runOptimizer()">Run v0.9 Walk-Forward</button>\n  </section>\n\n  <div id="status" class="status">\n    Choose your settings and start a scan.\n  </div>\n\n  <section>\n    <div class="title">\n      <div>\n        <label id="listlabel">1-MONTH SHORTLIST</label>\n        <h2 id="listtitle">Top 3 Candidates</h2>\n      </div>\n      <small id="updated"></small>\n    </div>\n    <div id="cards"></div>\n  </section>\n\n  <p class="foot">\n    Forecasts, signals and historical tests are research outputs, not guaranteed returns or investment advice.\n  </p>\n</main>\n\n<script>\nlet current=\'invest\';\n\nconst fmt=n=>new Intl.NumberFormat(\n  \'en-IN\',\n  {style:\'currency\',currency:\'INR\',maximumFractionDigits:0}\n).format(n);\n\nfunction effectiveMax(){\n  const v=+document.getElementById(\'maxPrice\').value;\n  return v>=5000 ? 0 : v;\n}\n\nfunction priceChanged(which){\n  const minEl=document.getElementById(\'minPrice\');\n  const maxEl=document.getElementById(\'maxPrice\');\n  let lo=+minEl.value, hi=+maxEl.value;\n\n  if(lo>hi){\n    if(which===\'min\') maxEl.value=lo;\n    else minEl.value=hi;\n  }\n  \n  updatePriceText();\n}\n\nfunction preset(lo,hi){\n  document.getElementById(\'minPrice\').value=lo;\n  document.getElementById(\'maxPrice\').value=hi;\n  updatePriceText();\n}\n\nfunction updatePriceText(){\n  const lo=+document.getElementById(\'minPrice\').value;\n  const hi=+document.getElementById(\'maxPrice\').value;\n  let text=\'\';\n\n  if(lo===0 && hi>=5000) text=\'Any affordable price\';\n  else if(lo===0) text=`Up to ${fmt(hi)}`;\n  else if(hi>=5000) text=`${fmt(lo)} and above`;\n  else text=`${fmt(lo)} – ${fmt(hi)}`;\n\n  document.getElementById(\'priceText\').textContent=text;\n}\n\nfunction mode(m,b){\n  current=m;\n  document.querySelectorAll(\'.tab\').forEach(x=>x.classList.remove(\'active\'));\n  b.classList.add(\'active\');\n  document.getElementById(\'cards\').innerHTML=\'\';\n\n  const day=m===\'day\';\n  const backtest=m===\'backtest\';\n  const lab=m===\'lab\';\n\n  document.getElementById(\'mainControls\').classList.toggle(\'hide\',backtest || lab);\n  document.getElementById(\'backtestControls\').classList.toggle(\'hide\',!backtest);\n  document.getElementById(\'labControls\').classList.toggle(\'hide\',!lab);\n  document.getElementById(\'riskbox\').classList.toggle(\'hide\',day || backtest || lab);\n  document.getElementById(\'riskpct\').classList.toggle(\'hide\',!day);\n  document.getElementById(\'pricePanel\').classList.toggle(\'hide\',!day);\n\n  if(lab){\n    document.getElementById(\'eyebrow\').textContent=\'STRATEGY RESEARCH LAB\';\n    document.getElementById(\'headline\').textContent=\'Research strategies with walk-forward validation.\';\n    document.getElementById(\'copy\').textContent=\'The v0.9 optimizer separates training, validation and unseen test periods so we can reject strategies that only look good on the data used to build them.\';\n    document.getElementById(\'listlabel\').textContent=\'OLD VS NEW\';\n    document.getElementById(\'listtitle\').textContent=\'Strategy Comparison\';\n    document.getElementById(\'status\').innerHTML=\'Run a comparison. A candidate is <b>not adopted automatically</b> just because it looks better in one historical sample.\';\n    return;\n  }\n\n  if(backtest){\n    document.getElementById(\'eyebrow\').textContent=\'MEASURED HISTORICAL PERFORMANCE\';\n    document.getElementById(\'headline\').textContent=\'Test the model instead of guessing its accuracy.\';\n    document.getElementById(\'copy\').textContent=\'Run historical tests and measure hit rate, expectancy, profit factor and NIFTY-relative performance. Intraday uses the same live rule set; the 1-month test is clearly marked as a technical-only proxy.\';\n    document.getElementById(\'listlabel\').textContent=\'BACKTEST RESULTS\';\n    document.getElementById(\'listtitle\').textContent=\'Model Performance\';\n    document.getElementById(\'status\').innerHTML=\'<b>No accuracy percentage is assumed.</b> Run a backtest to calculate results from historical data.\';\n    return;\n  }\n\n  document.getElementById(\'eyebrow\').textContent=\n    day?\'LIVE INTRADAY FINDER\':\'1-MONTH INVESTMENT FINDER\';\n\n  document.getElementById(\'headline\').textContent=\n    day?\'Find intraday setups inside your price range.\':\'Find strong 1-month stock candidates.\';\n\n  document.getElementById(\'copy\').textContent=\n    day\n    ?\'Filter stocks by price, then scan for BUY, SELL or NO TRADE using VWAP, EMA, RSI, volume and breakouts.\'\n    :\'Enter your investment amount and StockLens will rank the strongest candidates for the next month.\';\n\n  document.getElementById(\'go\').textContent=\n    day?\'Scan Intraday Setups\':\'Find Best Stocks\';\n\n  document.getElementById(\'listlabel\').textContent=\n    day?\'INTRADAY SHORTLIST\':\'1-MONTH SHORTLIST\';\n\n  document.getElementById(\'listtitle\').textContent=\n    day?\'Top Affordable Trade Setups\':\'Top 3 Candidates\';\n\n  document.getElementById(\'status\').textContent=\'Choose your settings and start a scan.\';\n}\n\nfunction backtestEngineChanged(){\n  const monthly=document.getElementById(\'btEngine\').value===\'monthly\';\n  document.getElementById(\'btWindowBox\').classList.toggle(\'hide\',monthly);\n  document.getElementById(\'btMonthlyBox\').classList.toggle(\'hide\',!monthly);\n}\n\nasync function run(){\n  const amount=+document.getElementById(\'amount\').value;\n  const limit=document.getElementById(\'limit\').value;\n  const minPrice=+document.getElementById(\'minPrice\').value;\n  const maxPrice=effectiveMax();\n  const st=document.getElementById(\'status\');\n\n  if(amount<1000){\n    alert(\'Enter at least ₹1,000\');\n    return;\n  }\n\n  st.textContent=current===\'day\'\n    ?\'Searching the NIFTY 50 for intraday setups inside your price range…\'\n    :\'Analyzing stocks for the 1-month ranking…\';\n\n  document.getElementById(\'cards\').innerHTML=\'\';\n\n  try{\n    let url;\n\n    if(current===\'day\'){\n      url=`/api/intraday?capital=${amount}&risk_pct=${document.getElementById(\'rp\').value}&limit_universe=${limit}&min_price=${minPrice}&max_price=${maxPrice}`;\n    }else{\n      url=`/api/portfolio?amount=${amount}&risk=${document.getElementById(\'risk\').value}&limit_universe=${limit}`;\n    }\n\n    const r=await fetch(url);\n    const d=await r.json();\n    if(!r.ok) throw Error(d.detail||\'Scan failed\');\n\n    document.getElementById(\'updated\').textContent=\n      \'Updated \'+new Date().toLocaleTimeString([],{hour:\'2-digit\',minute:\'2-digit\'});\n\n    if(current===\'day\'){\n      st.innerHTML=\n        `Analyzed <b>${d.analysed}</b> matching candidate(s) · `+\n        `<b>${d.matched_price_filter}</b> passed the exact price/affordability check · `+\n        `<b>${d.top.length}</b> trade setup(s).`;\n\n      document.getElementById(\'cards\').innerHTML=d.top.length\n      ? d.top.map((x,i)=>`\n        <article>\n          <div class="top">\n            <div>\n              <em>#${i+1}</em>\n              <h3>${x.symbol}</h3>\n              <small>Stock price ₹${Number(x.price).toFixed(2)}</small>\n            </div>\n            <div class="score">${x.signal}<small>${x.confidence}% model score</small></div>\n          </div>\n\n          <div class="forecast">\n            <div><small>Entry</small><b>₹${x.entry}</b></div>\n            <div><small>Stop Loss</small><b>₹${x.stop_loss}</b></div>\n            <div><small>Target 1</small><b>₹${x.target1}</b></div>\n            <div><small>Target 2</small><b>₹${x.target2}</b></div>\n          </div>\n\n          <div class="afford">\n            <div><small>Max affordable shares</small><b>${x.max_affordable_qty}</b></div>\n            <div><small>Risk-based quantity</small><b>${x.quantity}</b></div>\n            <div><small>Capital used</small><b>${fmt(x.capital_used)}</b></div>\n            <div><small>Cash left</small><b>${fmt(x.cash_left)}</b></div>\n          </div>\n\n          <div class="meta">\n            <span>Capital ${fmt(x.capital)}</span>\n            <span>Risk ${x.risk_pct}%</span>\n            <span>Signal ${new Date(x.signal_time).toLocaleTimeString()}</span>\n          </div>\n\n          <div class="why">\n            <div>\n              <b>Signal reasons</b>\n              <ul>${x.reasons.map(v=>`<li>${v}</li>`).join(\'\')}</ul>\n            </div>\n            <div>\n              <b>Risk rule</b>\n              <ul>\n                <li>Exit if stop-loss is hit.</li>\n                <li>Model score is not probability of profit.</li>\n              </ul>\n            </div>\n          </div>\n        </article>\n      `).join(\'\')\n      : `<div class="empty"><b>NO TRADE</b><br>No stock in your selected price range produced a strong enough setup.</div>`;\n\n    }else{\n      st.innerHTML=\n        `Analyzed <b>${d.analysed}</b> stock(s) · showing the strongest 1-month candidates.`;\n\n      document.getElementById(\'cards\').innerHTML=d.top.length\n      ? d.top.map((x,i)=>{\n          const e=x.one_month_estimate;\n          const a=x.affordability;\n          return `\n          <article>\n            <div class="top">\n              <div>\n                <em>#${i+1}</em>\n                <h3>${x.symbol}</h3>\n                <small>${x.company_name||\'\'}</small>\n              </div>\n              <div class="score">${Number(x.stocklens_score).toFixed(1)}<small>/100 model score</small></div>\n            </div>\n\n            <div class="afford">\n              <div><small>Current share price</small><b>${fmt(a.share_price)}</b></div>\n              <div><small>Approx. whole shares</small><b>${a.affordable_qty}</b></div>\n            </div>\n\n            <div class="forecast">\n              <div><small>Your capital</small><b>${fmt(amount)}</b></div>\n              <div><small>Estimated 1-month value</small><b>${fmt(e.estimated_value_low)} – ${fmt(e.estimated_value_high)}</b></div>\n              <div><small>Estimated return range</small><b>${e.expected_return_low_pct}% to ${e.expected_return_high_pct}%</b></div>\n              <div><small>Downside scenario</small><b>${fmt(e.downside_value)}</b></div>\n            </div>\n\n            <div class="meta">\n              <span>Model score confidence ${e.confidence}%</span>\n              <span>${x.recommendation}</span>\n              <span>Risk ${x.risk_level||\'—\'}</span>\n            </div>\n\n            <div class="why">\n              <div>\n                <b>Why it ranks well</b>\n                <ul>${(x.positives||[]).slice(0,4).map(v=>`<li>${v}</li>`).join(\'\')||\'<li>Composite model score.</li>\'}</ul>\n              </div>\n              <div>\n                <b>Warnings</b>\n                <ul>${(x.red_flags||[]).slice(0,3).map(v=>`<li>${v}</li>`).join(\'\')||\'<li>No major model warning.</li>\'}</ul>\n              </div>\n            </div>\n          </article>`;\n        }).join(\'\')\n      : `<div class="empty"><b>No candidate found.</b><br>Try scanning a wider universe.</div>`;\n    }\n\n  }catch(e){\n    st.textContent=\'Scan failed: \'+e.message;\n  }\n}\n\nfunction metric(label,value,sub=\'\'){\n  return `<div class="metric"><small>${label}</small><strong>${value}</strong>${sub?`<span>${sub}</span>`:\'\'}</div>`;\n}\n\nfunction renderBreakdown(title,rows,monthly=false){\n  if(!rows || !rows.length) return \'\';\n  return `<div class="breakdown-block">\n    <h3>${title}</h3>\n    <div class="table-wrap"><table>\n      <thead><tr>${\n        monthly\n        ?\'<th>Group</th><th>Samples</th><th>Positive 1M</th><th>Beat NIFTY</th><th>Avg return</th>\'\n        :\'<th>Group</th><th>Signals</th><th>T1 hit</th><th>Positive</th><th>Avg R</th>\'\n      }</tr></thead>\n      <tbody>${rows.map(r=>monthly\n        ?`<tr><td>${r.group}</td><td>${r.samples}</td><td>${r.positive_after_1m_rate}%</td><td>${r.beat_nifty_rate}%</td><td>${r.avg_return_pct}%</td></tr>`\n        :`<tr><td>${r.group}</td><td>${r.signals}</td><td>${r.target1_hit_rate}%</td><td>${r.positive_outcome_rate}%</td><td>${r.avg_r}R</td></tr>`\n      ).join(\'\')}</tbody>\n    </table></div>\n  </div>`;\n}\n\nasync function runBacktest(){\n  const engine=document.getElementById(\'btEngine\').value;\n  const limit=document.getElementById(\'btLimit\').value;\n  const st=document.getElementById(\'status\');\n  const cards=document.getElementById(\'cards\');\n\n  st.innerHTML=\'<b>Running historical backtest…</b> This can take a little longer than a normal scan.\';\n  cards.innerHTML=\'\';\n\n  try{\n    let url;\n    if(engine===\'intraday\'){\n      const period=document.getElementById(\'btWindow\').value;\n      url=`/api/backtest/intraday?limit_universe=${limit}&period=${period}&max_hold_bars=12`;\n    }else{\n      const period=document.getElementById(\'btMonthlyPeriod\').value;\n      url=`/api/backtest/monthly?limit_universe=${limit}&period=${period}&horizon_days=21&min_technical_score=65`;\n    }\n\n    const r=await fetch(url);\n    const d=await r.json();\n    if(!r.ok) throw Error(d.detail||\'Backtest failed\');\n\n    document.getElementById(\'updated\').textContent=\n      \'Tested \'+new Date().toLocaleTimeString([],{hour:\'2-digit\',minute:\'2-digit\'});\n\n    if(engine===\'intraday\'){\n      const m=d.metrics;\n      st.innerHTML=`Measured from <b>${m.signals_tested}</b> historical signal(s) across <b>${d.symbols_tested.join(\', \')}</b>. This is historical performance, not a future guarantee.`;\n\n      cards.innerHTML=`\n        <article class="accuracy-card">\n          <div class="scope good-scope"><b>✓ SAME LIVE INTRADAY RULES</b><span>${d.scope}</span></div>\n\n          <div class="metrics-grid">\n            ${metric(\'Signals tested\',m.signals_tested)}\n            ${metric(\'Target 1 hit rate\',m.target1_hit_rate+\'%\',\'T1 before expiry\')}\n            ${metric(\'Positive outcome rate\',m.positive_outcome_rate+\'%\')}\n            ${metric(\'Expectancy\',m.avg_r+\'R\',\'Average per signal\')}\n            ${metric(\'Profit factor\',m.profit_factor)}\n            ${metric(\'Max drawdown\',m.max_drawdown_r+\'R\')}\n          </div>\n\n          <div class="outcome-strip">\n            <span>🎯 T1 hits <b>${m.target1_hits}</b></span>\n            <span>🛑 Stops <b>${m.stop_hits}</b></span>\n            <span>⏱ Timeouts <b>${m.timeouts}</b></span>\n            <span>Avg winner <b>${m.avg_winner_r}R</b></span>\n            <span>Avg loser <b>${m.avg_loser_r}R</b></span>\n          </div>\n\n          ${renderBreakdown(\'BUY vs SELL\',d.by_signal)}\n          ${renderBreakdown(\'Performance by model score\',d.by_confidence)}\n          ${renderBreakdown(\'Performance by stock price\',d.by_price)}\n          ${renderBreakdown(\'Performance by time of day\',d.by_time)}\n\n          <div class="caveat"><b>Backtest limitations</b><ul>${d.limitations.map(x=>`<li>${x}</li>`).join(\'\')}</ul></div>\n        </article>`;\n\n    }else{\n      const m=d.metrics;\n      st.innerHTML=`Measured from <b>${m.samples_tested}</b> non-overlapping historical sample(s) across <b>${d.symbols_tested.join(\', \')}</b>.`;\n\n      cards.innerHTML=`\n        <article class="accuracy-card">\n          <div class="scope proxy-scope">\n            <b>⚠ 1-MONTH TECHNICAL PROXY</b>\n            <span>${d.scope}</span>\n          </div>\n\n          <div class="metrics-grid">\n            ${metric(\'Samples tested\',m.samples_tested)}\n            ${metric(\'Positive after ~1M\',m.positive_after_1m_rate+\'%\')}\n            ${metric(\'Beat NIFTY\',m.beat_nifty_rate+\'%\')}\n            ${metric(\'Average stock return\',m.avg_stock_return_pct+\'%\')}\n            ${metric(\'NIFTY average\',m.avg_nifty_return_pct+\'%\')}\n            ${metric(\'Average excess return\',m.avg_excess_return_pct+\'%\')}\n          </div>\n\n          ${renderBreakdown(\'Performance by technical score\',d.by_score,true)}\n\n          <div class="caveat important"><b>Why this is not full-model accuracy</b><ul>${d.limitations.map(x=>`<li>${x}</li>`).join(\'\')}</ul></div>\n        </article>`;\n    }\n\n  }catch(e){\n    st.textContent=\'Backtest failed: \'+e.message;\n  }\n}\n\n\nfunction compareMetric(label,oldv,newv,suffix=\'\'){\n  const oldN=Number(oldv), newN=Number(newv);\n  const better=(label.includes(\'Drawdown\')) ? newN<oldN : newN>oldN;\n  return `<div class="compare-row"><span>${label}</span><b>${oldv}${suffix}</b><b class="${better?\'better\':\'worse\'}">${newv}${suffix}</b></div>`;\n}\n\nasync function runLab(){\n  const engine=document.getElementById(\'labEngine\').value;\n  const limit=document.getElementById(\'labLimit\').value;\n  const st=document.getElementById(\'status\'), cards=document.getElementById(\'cards\');\n  st.innerHTML=\'<b>Testing baseline against v0.8 candidate…</b>\';\n  cards.innerHTML=\'\';\n  try{\n    const url=engine===\'intraday\'\n      ?`/api/research/intraday-compare?limit_universe=${limit}&period=1mo`\n      :`/api/research/monthly-compare?limit_universe=${limit}&period=2y`;\n    const r=await fetch(url),d=await r.json();\n    if(!r.ok) throw Error(d.detail||\'Comparison failed\');\n    const o=d.comparison.old,n=d.comparison.candidate;\n    document.getElementById(\'updated\').textContent=\'Compared \'+new Date().toLocaleTimeString([],{hour:\'2-digit\',minute:\'2-digit\'});\n    if(engine===\'intraday\'){\n      st.innerHTML=`Baseline <b>${o.signals}</b> signals vs candidate <b>${n.signals}</b>. Judge quality and sample size together.`;\n      cards.innerHTML=`<article class="accuracy-card">\n        <div class="scope good-scope"><b>🧪 EXPERIMENTAL v0.8 FILTERS</b><span>Not yet adopted as the live engine</span></div>\n        <div class="compare-head"><span>Metric</span><b>v0.7</b><b>v0.8 candidate</b></div>\n        ${compareMetric(\'Signals\',o.signals,n.signals)}\n        ${compareMetric(\'T1 hit rate\',o.t1_rate,n.t1_rate,\'%\')}\n        ${compareMetric(\'Positive rate\',o.positive_rate,n.positive_rate,\'%\')}\n        ${compareMetric(\'Expectancy\',o.avg_r,n.avg_r,\'R\')}\n        ${compareMetric(\'Profit factor\',o.profit_factor,n.profit_factor)}\n        ${compareMetric(\'Max Drawdown\',o.max_drawdown_r,n.max_drawdown_r,\'R\')}\n        <div class="caveat"><b>Candidate filters</b><ul>${d.comparison.candidate_rules.map(x=>`<li>${x}</li>`).join(\'\')}</ul></div>\n        <div class="caveat important"><b>Validation rule</b><p>${d.warning} We should only promote these rules after they also improve on a separate unseen period.</p></div>\n      </article>`;\n    }else{\n      st.innerHTML=`Baseline <b>${o.samples}</b> samples vs candidate <b>${n.samples}</b>. This remains a technical proxy.`;\n      cards.innerHTML=`<article class="accuracy-card">\n        <div class="scope proxy-scope"><b>🧪 1-MONTH CANDIDATE FILTER</b><span>Technical proxy only</span></div>\n        <div class="compare-head"><span>Metric</span><b>v0.7</b><b>v0.8 candidate</b></div>\n        ${compareMetric(\'Samples\',o.samples,n.samples)}\n        ${compareMetric(\'Positive after 1M\',o.positive_rate,n.positive_rate,\'%\')}\n        ${compareMetric(\'Beat NIFTY\',o.beat_nifty_rate,n.beat_nifty_rate,\'%\')}\n        ${compareMetric(\'Average return\',o.avg_return,n.avg_return,\'%\')}\n        ${compareMetric(\'Average excess\',o.avg_excess,n.avg_excess,\'%\')}\n        <div class="caveat"><b>Candidate filters</b><ul>${d.comparison.candidate_rules.map(x=>`<li>${x}</li>`).join(\'\')}</ul></div>\n        <div class="caveat important"><b>Important</b><p>${d.warning}</p></div>\n      </article>`;\n    }\n  }catch(e){st.textContent=\'Comparison failed: \'+e.message}\n}\n\n\nasync function runOptimizer(){\n const limit=Math.max(5,+document.getElementById(\'labLimit\').value),st=document.getElementById(\'status\'),cards=document.getElementById(\'cards\');\n st.innerHTML=\'<b>Running walk-forward optimizer…</b> This uses several years of historical data.\';cards.innerHTML=\'\';\n try{\n  const r=await fetch(`/api/research/walk-forward?limit_universe=${limit}&period=5y`),d=await r.json();\n  if(!r.ok)throw Error(d.detail||\'Optimizer failed\');\n  const t=d.train,v=d.validation,u=d.unseen_test,b=d.baseline_unseen_test;\n  const verdict=d.approved_for_live_candidate?\'<span class="verdict pass">PASS</span>\':\'<span class="verdict fail">REJECT</span>\';\n  st.innerHTML=`Tested <b>${d.total_samples}</b> historical samples. ${verdict}`;\n  const row=(l,a,c,e)=>`<div class="wf-row"><span>${l}</span><b>${a}</b><b>${c}</b><b>${e}</b></div>`;\n  const rules=Object.entries(d.selected_rule).map(([k,x])=>`<li>${k.replaceAll(\'_\',\' \')}: <b>${x}</b></li>`).join(\'\');\n  cards.innerHTML=`<article class="accuracy-card"><div class="scope good-scope"><b>v0.9 WALK-FORWARD</b><span>Train → Validation → Unseen Test</span></div>\n   <div class="wf-head"><span>Metric</span><b>Train</b><b>Validation</b><b>Unseen</b></div>\n   ${row(\'Samples\',t.samples,v.samples,u.samples)}${row(\'Positive after 1M\',t.positive_rate+\'%\',v.positive_rate+\'%\',u.positive_rate+\'%\')}\n   ${row(\'Beat NIFTY\',t.beat_nifty_rate+\'%\',v.beat_nifty_rate+\'%\',u.beat_nifty_rate+\'%\')}\n   ${row(\'Average return\',t.avg_return+\'%\',v.avg_return+\'%\',u.avg_return+\'%\')}\n   ${row(\'Excess vs NIFTY\',t.avg_excess+\'%\',v.avg_excess+\'%\',u.avg_excess+\'%\')}\n   <div class="baseline-box"><b>UNSEEN comparison</b><div>v0.9 excess <strong>${u.avg_excess}%</strong></div><div>v0.7 excess <strong>${b.avg_excess}%</strong></div><div>v0.9 beat NIFTY <strong>${u.beat_nifty_rate}%</strong></div><div>v0.7 beat NIFTY <strong>${b.beat_nifty_rate}%</strong></div></div>\n   <div class="caveat"><b>Selected rules</b><ul>${rules}</ul></div>\n   <div class="caveat important"><b>Decision</b><p>PASS requires positive unseen excess return, >50% NIFTY-beating rate, enough unseen samples and improvement over baseline.</p></div></article>`;\n }catch(e){st.textContent=\'Walk-forward optimizer failed: \'+e.message}\n}\n\nupdatePriceText();\nbacktestEngineChanged();\n</script>\n</body>\n</html>\n'
